/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    CustInvoiceJour custInvoiceJour;
    CustInvoiceTrans custInvoiceTrans;
    MarkupTrans markupTrans;
    InventTransOrigin inventTransOrigin;
    InventTrans inventTrans;
    date startDate = mkDate(1, 1, 2010);
    date endDate = mkDate(31, 12, 2030);

    while select forupdate custInvoiceJour
        where custInvoiceJour.InvoiceDate >= startDate
        && custInvoiceJour.InvoiceDate <= endDate
    {
        ttsbegin;
        while select forupdate markupTrans 
            where markupTrans.TransTableId == custInvoiceJour.TableId
            && markupTrans.TransRecId == custInvoiceJour.RecId
        {
            markupTrans.doDelete();
        }

        while select forupdate custInvoiceTrans
            where custInvoiceTrans.InvoiceId == custInvoiceJour.InvoiceId
        {
            while select forupdate inventTransOrigin
                where inventTransOrigin.InventTransId == custInvoiceTrans.InventTransId
            {
                while select forupdate inventTrans
                    where inventTrans.InventTransOrigin == inventTransOrigin.RecId
                {
                    inventTrans.doDelete();
                }

                inventTransOrigin.doDelete();
            }
            while select forupdate markupTrans
            where markupTrans.TransTableId == custInvoiceTrans.TableId
            && markupTrans.TransRecId == custInvoiceTrans.RecId
            {
                markupTrans.doDelete();
            }

            custInvoiceTrans.doDelete();             
        }
        custInvoiceJour.doDelete();
        ttscommit;
    }
}
